from pathlib import Path
import csv,re
r=Path(__file__).resolve().parent
files=sorted((r/'validation_framework/integration').glob('master_catalog_*.csv'))
if not files:raise SystemExit('ERROR: no master')
with files[-1].open(encoding='utf-8-sig',newline='') as f:rows=list(csv.DictReader(f))
assert [x['component_id'] for x in rows]==[f'CMP-CAM-{i:04d}' for i in range(1,len(rows)+1)]
readme=r/'README.md'; text=readme.read_text(encoding='utf-8') if readme.exists() else '# PAI-SG Camera Sensor Catalog\n'
# Remove BOTH historical autogenerated index blocks, including the stale table.
text=re.sub(r'(?ms)^<!-- PAI-SG-CAMERA-CATALOG:START -->\n.*?^<!-- PAI-SG-CAMERA-CATALOG:END -->\n?', '',text)
text=re.sub(r'(?ms)^## Component index\n<!-- CAMERA_CATALOG_START -->\n.*?^<!-- CAMERA_CATALOG_END -->\n?', '',text)
text=re.sub(r'(?ms)^## Component Index\n<!-- CAMERA_CATALOG_START -->\n.*?^<!-- CAMERA_CATALOG_END -->\n?', '',text)
text=re.sub(r'(?m)^\*\*Registered: .*?\*\*\s*\n','',text)
text=text.rstrip()+'\n\n'
lines=['<!-- CAMERA_CATALOG_START -->','## Component Index',f'**Registered: {len(rows)} / 160 ({len(rows)/160*100:.3f}%) — Waves 1–{len(rows)//5}**','','| Component ID | Manufacturer | Model | Category | Status | Verification | Algorithm Test |','|---|---|---|---|---|---|---|']
for x in rows:
 cid=x['component_id'];lines.append(f"| [{cid}](component_cards/{cid}.md) | {x['manufacturer']} | {x['model']} | {x['primary_category_code']} | listed | not_verified | not_tested |")
lines+=['<!-- CAMERA_CATALOG_END -->','']
readme.write_text(text+'\n'.join(lines),encoding='utf-8')
print(f'README updated: {len(rows)} entries; single canonical table')
